    ];
    // Centrée sur le gap (169..183 recouvre 3 px de chaque brique), et 1 px sous leur face
    // basse : l'axe vertical gagne pour les deux.
    state.ball = { x: 176, y: 126, r: BALL_R, vx: 6, vy: -60 };

