edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face is resolved by `bounceOffBrick` below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Two penetrations closer than this count as "equal": a corner hit.
const CORNER_EPS = 1e-6;

// Deflects the ball off a brick it overlaps (issue #1).
//
// Per face: the axis with the *smaller* penetration is the face that was hit —
// flip `vy` on a top/bottom hit, `vx` on a side hit, and leave the other
// component exactly as it was. Equal penetrations on both axes mean a
// diagonal/corner hit: flip both components. In every case the ball is pushed
// back out of the brick rectangle, otherwise it still overlaps on the next
// frame and re-flips forever (sticky bounce).
function bounceOffBrick(ball, brick) {
  // Penetration depth on each side of the brick.
  const left = ball.x + ball.r - brick.x;              // entered from the left
  const right = brick.x + brick.w - (ball.x - ball.r); // entered from the right
  const top = ball.y + ball.r - brick.y;               // entered from above
  const bottom = brick.y + brick.h - (ball.y - ball.r); // entered from below

  const penX = Math.min(left, right);
  const penY = Math.min(top, bottom);

  if (Math.abs(penX - penY) <= CORNER_EPS) {
    // Corner: flip both components and push out diagonally.
    if (left <= right) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (top <= bottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else if (penX < penY) {
    // Side hit: only the horizontal component flips.
    if (left < right) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else {
    // Top/bottom hit: only the vertical component flips.
    if (top < bottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
}

// Kills every brick the ball overlaps, awards score/combo, then applies
// exactly ONE bounce against the brick with the smallest penetration (the face
// actually struck). The grid gap is 8 px and the ball 14 px across, so every
// seam overlaps two bricks in the same pass: without the once-only guard, a
// `vy = -vy` applied twice cancels out and the ball goes through.
// Returns true if a bounce was applied.
function resolveBricks(state) {
  const { ball, bricks } = state;
  let struck = null;
  let bestPen = Infinity;

  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const pen = Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    );
    if (pen < bestPen) {
      bestPen = pen;
      struck = brick;
    }
  }

  if (struck) {
    bounceOffBrick(ball, struck);
    return true;
  }
  return false;
}

