    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks. Detection is discrete (position before / after the move), so we
  // sweep between the two positions: at level 6, `ballSpeed(6)` = 710 px/s and
  // a stuttered frame is capped at 50 ms — 35.5 px per step against 34 px to
  // cross (`BRICK_H` + diameter) — so without the sweep the ball jumps over a
  // brick without ever touching it (tunnelling). Sub-steps are at most one
  // ball radius apart, far under the diameter needed to skip a brick.
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const dist = Math.hypot(dx, dy);
  const samples = Math.max(1, Math.ceil(dist / ball.r));
  for (let i = 0; i <= samples; i++) {
    const t = i / samples;
    ball.x = prevX + dx * t;
    ball.y = prevY + dy * t;
    // The first bounce (with its push-out) ends the sweep: the ball is now
    // outside every brick, and resolving twice in one pass would cancel out.
    if (resolveBricks(state)) break;
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

